function debounce(fn, ms) {
  let timer = null;                 // lives in the closure
  return function (...args) {
    clearTimeout(timer);            // cancel the pending call
    timer = setTimeout(() => fn.apply(this, args), ms);
  };
}

// usage
input.addEventListener('input', debounce(e => search(e.target.value), 300));

// throttle for contrast: leading call, then ignore for ms
function throttle(fn, ms) {
  let last = 0;
  return function (...args) {
    const now = Date.now();
    if (now - last >= ms) { last = now; fn.apply(this, args); }
  };
}

practice.solution:
```js
function debounce(fn, ms) {
  let timer = null, lastArgs = null, lastThis = null;
  function run() { timer = null; fn.apply(lastThis, lastArgs); }
  function debounced(...args) { lastArgs = args; lastThis = this; clearTimeout(timer); timer = setTimeout(run, ms); }
  debounced.cancel = () => { clearTimeout(timer); timer = null; };
  debounced.flush  = () => { if (timer) { clearTimeout(timer); run(); } };
  return debounced;
}
```
